#!/bin/bash

# Rewrites tenant vhosts generated by releases up to 1.2.2 to match the current
# apache-vhost.template. Those used FollowSymLinks with AllowOverride All, so a
# tenant could symlink any file www-data can read (the panel .env included) into
# its document root and have Apache serve it. SymLinksIfOwnerMatch only follows a
# link owned by the target's owner, and the narrowed AllowOverride stops a
# tenant .htaccess from switching FollowSymLinks back on.
#
# Safe to run repeatedly. Called by laranode-upgrade.sh, and in the Docker image
# on every boot after the saved vhosts are restored.
#
# Usage (as root): laranode-harden-vhosts.sh [sites-available dir]

SITES_DIR=${1:-/etc/apache2/sites-available}

OLD_OPTIONS='Options Indexes FollowSymLinks'
NEW_OPTIONS='Options Indexes SymLinksIfOwnerMatch'
OLD_OVERRIDE='AllowOverride All'
NEW_OVERRIDE='AllowOverride AuthConfig FileInfo Indexes Limit Options=Indexes,MultiViews,SymLinksIfOwnerMatch'

BACKUP_DIR=$(mktemp -d)
trap 'rm -rf "$BACKUP_DIR"' EXIT

changed=()

for file in "$SITES_DIR"/*.conf; do
    [ -f "$file" ] || continue

    # only vhosts Laranode generated for a tenant
    grep -q '/home/[^/]*_ln/domains/' "$file" || continue

    updated=""
    modified=0
    while IFS= read -r line || [ -n "$line" ]; do
        # match the exact lines the old template produced, keeping indentation;
        # anything an admin customised is reported below instead of guessed at
        trimmed="${line#"${line%%[![:space:]]*}"}"
        indent="${line%"$trimmed"}"
        trimmed="${trimmed%"${trimmed##*[![:space:]]}"}"

        if [ "$trimmed" = "$OLD_OPTIONS" ]; then
            line="$indent$NEW_OPTIONS"
            modified=1
        elif [ "$trimmed" = "$OLD_OVERRIDE" ]; then
            line="$indent$NEW_OVERRIDE"
            modified=1
        fi
        updated+="$line"$'\n'
    done < "$file"

    if [ "$modified" -eq 1 ]; then
        cp -p "$file" "$BACKUP_DIR/"
        # cat keeps the file's owner and mode
        printf '%s' "$updated" | cat > "$file"
        changed+=("$file")
    fi

    if grep -qi 'FollowSymLinks' "$file"; then
        echo "WARNING: $file still enables FollowSymLinks; review it by hand."
    fi
done

if [ ${#changed[@]} -gt 0 ] && command -v apache2ctl >/dev/null 2>&1; then
    if ! apache2ctl configtest >/dev/null 2>&1; then
        echo "Apache rejected the updated vhosts; restoring the previous versions."
        for file in "${changed[@]}"; do
            cp -p "$BACKUP_DIR/$(basename "$file")" "$file"
        done
        exit 1
    fi
fi

echo "Hardened ${#changed[@]} tenant vhost file(s)."

# A tenant .htaccess may no longer set FollowSymLinks, and Apache answers any
# request under one that does with a 500. Name them so the admin can fix them.
htaccess=$(grep -rlis --include=.htaccess 'FollowSymLinks' /home/*_ln/domains 2>/dev/null)
if [ -n "$htaccess" ]; then
    echo ""
    echo "These .htaccess files set FollowSymLinks, which tenant sites can no longer do."
    echo "Change it to SymLinksIfOwnerMatch or remove the line, otherwise the site returns 500:"
    echo "$htaccess" | sed 's/^/  /'
fi
